"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["8321"],{60485(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.termo_formulario.codigo_obrigatorio","status":422,"titulo":"O c\xf3digo do termo exigido \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.termo_formulario.codigo_obrigatorio","requisitos":["UNI-REQ-0086"],"oQueAconteceu":["O `codigo` de um termo exigido pelo formul\xe1rio est\xe1 vazio ou s\xf3 com espa\xe7os. O c\xf3digo \xe9 o identificador da exig\xeancia do termo no formul\xe1rio, est\xe1vel mesmo entre dois termos do cat\xe1logo com o mesmo nome (UNI-REQ-0086). A mensagem \xe9 \\"O c\xf3digo do termo exigido \xe9 obrigat\xf3rio.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `termos[i].codigo`, em que `i` \xe9 a posi\xe7\xe3o do termo na lista enviada (nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`). Cada termo recusado tem a pr\xf3pria entrada. Nada \xe9 gravado.","A recusa vale para o texto presente. A propriedade `codigo` ausente ou nula \xe9 recusada antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo. Um termo nulo dentro da lista tem recusa pr\xf3pria: na grava\xe7\xe3o dos termos do processo, a de [lista de termos ou termo nulo](/erros/uniplus.selecao.termo_exigido_formulario.entrada_malformada) e, nos modelos, a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada).","Nas duas grava\xe7\xf5es a confer\xeancia da forma de cada termo (c\xf3digo e ordem) acumula com as demais recusas do pedido, sem interromper na primeira. Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Informe em `codigo` um texto de 1 a 60 caracteres, distinto do de cada outro termo do formul\xe1rio."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos termos do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Termo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);